INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('douanier', 'pa', 'socle', 'Sans objet : la classe beta interdit tout debit.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('douanier', 'position_leader', 'institution', 'La position d''un agent de la force publique EST son poste : le miroir la derive du batiment ou vit son effectif. Aucune RPC ne le deplace, et il ne suit aucun leader. Ce n''est donc pas un magasin concurrent a basculer : il n''y a personne a qui prendre l''autorite. Rendre le socle autoritaire ici n''ajouterait aucune capacite et lui ferait seulement cesser de suivre son institution. Deplacer un agent est une mecanique qui n''existe pas ; l''inventer demanderait un arbitrage.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('douanier', 'possessions', 'socle', 'Aucune possession dans le magasin historique.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('douanier', 'propriete', 'socle', NULL);
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('employe', 'argent', 'socle', 'Bascule du 27/09/2026 : employe_recruter / employe_liberer ecrivent pnj_membres, et la production ne contenait aucun employe a migrer. Les structures clientes (state.employes, escort_active) deviennent des projections d''affichage.');
