INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('soldat', 'argent', 'socle', 'Le blob militaire n''a aucune notion d''argent : cet axe n''a jamais eu de concurrent.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('soldat', 'pa', 'socle', 'Bascule checkpoint A : consommation Alpha generique via pnj_pa_debiter/crediter/fixer ; le metier ne fixe que les couts.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('soldat', 'position_leader', 'socle', 'Bascule checkpoint A : 5 ecrivains de position/leader passent par pnj_membres puis militaire_blob_projeter.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('soldat', 'possessions', 'socle', 'Bascule le 27/09/2026 (lot 4). Les trois ecrivains -- equiper_accessoire, gilet_absorber, ordre_collectif -- ecrivent le socle. Le miroir de cet axe est arrete : `accessoires` dans le blob est un vestige gele, conserve mais plus lu.');
INSERT INTO public.pnj_axes_autorite (famille, axe, autorite, note) VALUES ('soldat', 'propriete', 'socle', 'Propriete et autorite sont resolues par le socle et le registre des institutions depuis le 27/09. Le blob ne decide que le PERIMETRE -- section ou reserve -- qui est une donnee metier et le reste.');
